const CATEGORY_ALIASES = {
  guide: 'guide', '가이드 위반': 'guide',
  readiness: 'readiness', '진행 준비': 'readiness',
  schedule: 'schedule', '일정 위험': 'schedule',
  consistency: 'consistency', '데이터 불일치': 'consistency',
  integration: 'integration', '연동 문제': 'integration',
};

export const ISSUE_CATEGORIES = {
  guide: '가이드 위반',
  readiness: '진행 준비',
  schedule: '일정 위험',
  consistency: '데이터 불일치',
  integration: '연동 문제',
};

const CATALOG = {
  MISSING_TITLE: ['guide', '작업명 입력 필요', '작업 담당자'],
  MISSING_SPRINT: ['guide', '스프린트 입력 필요', '작업 담당자'],
  MISSING_STATUS: ['guide', '상태 입력 필요', '작업 담당자'],
  MISSING_DESCRIPTION: ['guide', '작업 설명 입력 필요', 'PD 또는 메인 기획자'],
  MISSING_REQUIRED_OWNERS: ['guide', 'PD·팀장 담당자 지정 필요', 'PD 또는 메인 기획자'],
  MISSING_START_DATE: ['guide', '기간 입력 필요', '작업 담당자'],
  MISSING_DUE_DATE: ['guide', '기간 입력 필요', '작업 담당자'],
  MISSING_PRIORITY: ['guide', '우선순위 입력 필요', '작업 담당자'],
  MISSING_BRANCH: ['guide', '브랜치 입력 필요', '프로젝트 개발 담당자'],
  MISSING_CONFIRMATION_COMMENT_TAG: ['guide', '확인 요청 태그 필요', 'PD 또는 메인 기획자'],
  MISSING_COMPLETED_DATE: ['guide', '완료일 입력 필요', '작업 담당자'],
  INVALID_HIERARCHY: ['guide', '계층 수정 필요', 'PD 또는 메인 기획자'],
  MISSING_PROJECT: ['guide', '프로젝트 연결 필요', '프로젝트 운영 담당자'],
  MISSING_SPEC: ['guide', '상위 작업 연결 필요', 'PD 또는 메인 기획자'],
  MISSING_ASSIGNEE: ['guide', '담당자 지정 필요', '프로젝트 운영 담당자'],
  DATE_RANGE_MISMATCH: ['guide', '기간 확인 필요', '작업 담당자'],
  PLANNED_START_DATE_PASSED: ['guide', '상태 변경 필요', '작업 담당자'],
  PARENT_CHILD_STATUS_MISMATCH: ['guide', '상하위 상태 확인', 'PD 또는 메인 기획자'],
  REOPENED_COMPLETED_ITEM: ['guide', '신규 작업 분리 필요', 'PD 또는 메인 기획자'],
  COMPLETION_DATE_RELATION: ['guide', '완료일 관계 확인', '작업 담당자'],
  MISSING_DELAY_REASON: ['guide', '지연 사유 입력 필요', 'PD 또는 메인 기획자'],
  MISSING_DELAY_DATE_HISTORY: ['guide', '변경 일정 입력 필요', 'PD 또는 메인 기획자'],
  MISSING_DELAY_OWNER_TAG: ['guide', '지연 담당자 태그 필요', 'PD 또는 메인 기획자'],
  OVERDUE: ['schedule', '지연 기록 필요', 'PD 또는 메인 기획자'],
  PAST_SPRINT_NOT_STARTED: ['schedule', '지난 스프린트 미착수', 'PD 또는 메인 기획자'],
  CURRENT_SPRINT_SETUP_REQUIRED: ['readiness', '진행 준비 필요', 'PD 또는 메인 기획자'],
  GIT_NOTION_ACTIVITY_MISMATCH: ['consistency', 'Notion·Git 상태 확인', '프로젝트 개발 담당자'],
  UNMAPPED_GIT_ACTIVITY: ['integration', 'Git 작업 연결 필요', '프로젝트 개발 담당자'],
  MISSING_GIT_URL: ['integration', 'Git URL 입력 필요', '프로젝트 개발 담당자'],
  GIT_AUTH_REQUIRED: ['integration', 'Git 인증 설정 필요', '프로젝트 개발 담당자'],
  GIT_COLLECTION_FAILED: ['integration', 'Git 수집 확인 필요', '프로젝트 개발 담당자'],
  GIT_FETCH_FAILED: ['integration', 'Git 수집 확인 필요', '프로젝트 개발 담당자'],
  GIT_PARTIAL_FETCH: ['integration', 'Git 부분 수집 확인 필요', '프로젝트 개발 담당자'],
  GIT_URL_INVALID: ['integration', 'Git URL 수정 필요', '프로젝트 개발 담당자'],
  GIT_URL_MISSING: ['integration', 'Git URL 입력 필요', '프로젝트 개발 담당자'],
  RULE_NOT_EVALUATED: ['integration', '규칙 대조 미실행', '프로젝트 운영 담당자'],
};

const SEVERITY_RANK = { error: 0, warning: 1, check: 2, info: 3 };

export function issuePresentation(issue = {}) {
  const fallback = CATALOG[issue.type] || ['guide', issue.label || '관리 확인 필요', '작업 담당자'];
  const category = CATEGORY_ALIASES[issue.category] || fallback[0];
  return {
    category,
    categoryLabel: ISSUE_CATEGORIES[category],
    label: issue.label || fallback[1],
    recommendedAction: issue.recommendedAction || 'Notion의 해당 항목을 확인하고 필요한 정보를 수정하세요.',
    responsibleRole: issue.responsibleRole || fallback[2],
    actionTarget: issue.actionTarget || fallbackActionTarget(issue, category),
  };
}

function fallbackActionTarget(issue, category) {
  if (issue.workItemId) return 'work-item';
  if (issue.specId) return 'spec';
  if (category === 'integration' && !['UNMAPPED_GIT_ACTIVITY', 'GIT_URL_MISSING', 'GIT_URL_INVALID'].includes(issue.type)) return 'git-repository';
  return 'project';
}

export function primaryActionSummary(issues = []) {
  if (!issues.length) return { label: '정상', tone: 'normal', otherCount: 0 };
  const ordered = [...issues].sort((left, right) => (SEVERITY_RANK[left.severity] ?? 9) - (SEVERITY_RANK[right.severity] ?? 9));
  const primary = ordered[0];
  const presentation = issuePresentation(primary);
  return {
    label: `${presentation.label}${ordered.length > 1 ? ` 외 ${ordered.length - 1}건` : ''}`,
    tone: primary.severity || 'check',
    otherCount: Math.max(0, ordered.length - 1),
  };
}

export function issueMatchesCategory(issue, category) {
  return !category || issuePresentation(issue).category === category;
}

function matchesBriefingFilter(item, filters = {}) {
  if (filters.project && item.project !== filters.project) return false;
  if (filters.team && item.team !== filters.team) return false;
  if (filters.assignee && !(item.assignees || []).includes(filters.assignee)) return false;
  return true;
}

export function briefingDetailItems(dashboard, detail, filters = {}) {
  const active = (dashboard.workItems || []).filter(item => !['완료', '일시 정지', '정지', '중단'].includes(item.status));
  if (detail === 'projects') return (dashboard.projects || []).filter(project => project.stats?.inProgress + project.stats?.planned + project.stats?.review > 0);
  if (detail === 'work-items') return active.filter(item => item.status === '진행 중' && matchesBriefingFilter(item, filters));
  if (detail === 'overdue') return active.filter(item => item.overdueDays > 0 && matchesBriefingFilter(item, filters));
  if (detail === 'guide') return (dashboard.guideViolationItems
    || active.filter(item => (item.issues || []).some(issue => issueMatchesCategory(issue, 'guide'))))
    .filter(item => matchesBriefingFilter(item, filters));
  if (detail === 'setup') return (dashboard.progressSetupItems || []).filter(item => matchesBriefingFilter(item, filters));
  return [];
}

function cleanShareText(value, fallback = '-') {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  return text || fallback;
}

function uniqueWorkItems(items = []) {
  const unique = new Map();
  for (const item of items) {
    const key = item.id || `${item.project || ''}:${item.title || ''}:${item.url || ''}`;
    if (!unique.has(key)) {
      unique.set(key, { ...item, issues: [...(item.issues || [])] });
      continue;
    }
    const existing = unique.get(key);
    const issueKeys = new Set((existing.issues || []).map(issue => `${issue.type || ''}:${issue.message || ''}`));
    for (const issue of item.issues || []) {
      const issueKey = `${issue.type || ''}:${issue.message || ''}`;
      if (!issueKeys.has(issueKey)) existing.issues.push(issue);
    }
  }
  return [...unique.values()];
}

export function slackWorkItemsMessage(items = [], {
  title = '확인할 작업항목',
  generatedAt = null,
  dashboardUrl = null,
  category = null,
  issueType = null,
} = {}) {
  const rows = uniqueWorkItems(items);
  const header = `*${cleanShareText(title)} · ${rows.length}건*`;
  const lines = [header];
  if (generatedAt) lines.push(`_기준: ${cleanShareText(generatedAt).replace('T', ' ').slice(0, 16)}_`);

  for (const item of rows) {
    const issues = (item.issues || []).filter(issue =>
      (!category || issueMatchesCategory(issue, category))
      && (!issueType || issue.type === issueType));
    const issueLabels = [...new Set(issues.map(issue => issuePresentation(issue).label))];
    const assignees = (item.assignees || []).map(name => cleanShareText(name)).join(', ') || '미지정';
    const period = `${cleanShareText(item.start)} → ${cleanShareText(item.due)}${item.overdueDays > 0 ? ` · ${item.overdueDays}일 초과` : ''}`;
    lines.push(
      '',
      `• *${cleanShareText(item.project, '프로젝트 미분류')} · ${cleanShareText(item.title, '제목 없음')}*`,
      `  상태: ${cleanShareText(item.status, '미정')} · 담당자: ${assignees}`,
      `  기간: ${period}`,
    );
    if (issueLabels.length) lines.push(`  확인: ${issueLabels.join(' · ')}`);
    if (item.url) lines.push(`  Notion: ${item.url}`);
  }

  if (dashboardUrl) lines.push('', `대시보드: ${dashboardUrl}`);
  return lines.join('\n');
}

export function dashboardShareUrl(baseUrl, state = {}) {
  const url = new URL(baseUrl);
  url.search = '';
  const tab = ['briefing', 'projects', 'people', 'checks'].includes(state.tab) ? state.tab : 'briefing';
  url.searchParams.set('tab', tab);
  if (tab === 'briefing' && ['projects', 'work-items', 'overdue', 'guide', 'setup', 'git'].includes(state.briefingDetail)) {
    url.searchParams.set('detail', state.briefingDetail);
    const filters = state.briefingFilters?.[state.briefingDetail] || {};
    if (filters.project) url.searchParams.set('briefingProject', filters.project);
    if (filters.team) url.searchParams.set('briefingTeam', filters.team);
    if (filters.assignee) url.searchParams.set('briefingAssignee', filters.assignee);
  }
  if (tab === 'checks') {
    const filters = state.checkFilters || {};
    if (filters.project) url.searchParams.set('checkProject', filters.project);
    if (filters.category) url.searchParams.set('checkCategory', filters.category);
    if (filters.issueType) url.searchParams.set('checkIssue', filters.issueType);
  }
  return url.toString();
}

const CONNECTED = new Set(['ok', 'connected', 'inactive', 'no-activity', 'no_activity']);
const AUTH = new Set(['auth-required', 'auth_required', 'authentication_required', 'unauthorized', 'not-accessible']);
const FAILED = new Set(['failed', 'error', 'collection-failed', 'collection_failed', 'invalid-url']);

function normalizedRepositoryStatus(repository) {
  return String(repository?.status || 'connected').toLowerCase();
}

export function gitTrustSummary(git = {}, projects = []) {
  const repositories = git.repositories || [];
  const total = projects.length || repositories.length;
  const statuses = repositories.map(normalizedRepositoryStatus);
  const errors = (git.errors || []).map(error => String(error?.message || error)).join(' ').toLowerCase();
  const hasAuthError = statuses.some(status => AUTH.has(status)) || AUTH.has(String(git.status || '').toLowerCase()) || /401|403|auth|token|인증/.test(errors);
  const connected = repositories.filter(repository => CONNECTED.has(normalizedRepositoryStatus(repository))).length;
  const configured = projects.length
    ? projects.filter(project => project.gitUrl || project.config?.gitUrl || project.git?.url).length
    : repositories.filter(repository => !['missing-url', 'missing_url'].includes(normalizedRepositoryStatus(repository))).length;
  if (hasAuthError) return { label: 'Git 인증 필요', tone: 'partial', connected, total };
  if (!configured) return { label: 'Git URL 미입력', tone: 'partial', connected: 0, total };
  if (statuses.includes('partial')) return { label: 'Git 부분 수집', tone: 'partial', connected, total };
  if (connected && (connected < total || statuses.some(status => FAILED.has(status)) || git.errors?.length)) return { label: 'Git 부분 수집', tone: 'partial', connected, total };
  if (!connected && (statuses.some(status => FAILED.has(status)) || git.errors?.length)) return { label: 'Git 수집 실패', tone: 'unavailable', connected: 0, total };
  return { label: `Git ${connected}/${total || connected} 연결`, tone: 'ok', connected, total: total || connected };
}

export function gitRepositoryStatus(repository = {}) {
  const status = normalizedRepositoryStatus(repository);
  if (status === 'not-accessible') return 'Git 권한 또는 URL 확인';
  if (AUTH.has(status)) return 'Git 인증 필요';
  if (FAILED.has(status)) return 'Git 수집 실패';
  if (status === 'missing-url' || status === 'missing_url') return 'Git URL 미입력';
  if (status === 'partial') return 'Git 부분 수집';
  return repository.commitCount > 0 || repository.lastActivityAt || repository.recentGitAt ? '연결됨 · 최근 활동 있음' : '연결됨 · 최근 활동 없음';
}

import { briefingDetailItems, gitRepositoryStatus, issuePresentation, primaryActionSummary } from './dashboard-management.js';

import { sprintOverviewHtml } from './sprint-overview.js';

const SEVERITY_RANK = { error: 0, warning: 1, check: 2, info: 3 };
const esc = value => String(value ?? '').replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]));
const safeUrl = value => /^(https?:\/\/|#)/.test(String(value || '')) ? value : '#';
const fmt = value => value ? String(value).replace('T', ' ').slice(0, 16) : '-';

function filterOptions(values, current) {
  return `<option value="">전체</option>${[...new Set(values.filter(Boolean))].sort((a, b) => String(a).localeCompare(String(b), 'ko')).map(value => `<option value="${esc(value)}" ${value === current ? 'selected' : ''}>${esc(value)}</option>`).join('')}`;
}

function briefingFilterHtml(items, filters) {
  const teams = items.map(item => item.team);
  const assignees = items.flatMap(item => item.assignees || []);
  return `<div class="toolbar briefing-filters"><label>프로젝트<select data-briefing-filter="project">${filterOptions(items.map(item => item.project), filters.project)}</select></label><label>팀<select data-briefing-filter="team">${filterOptions(teams, filters.team)}</select></label><label>담당자<select data-briefing-filter="assignee">${filterOptions(assignees, filters.assignee)}</select></label><button type="button" class="reset" data-action="reset-briefing-filters">필터 초기화</button></div>`;
}

export function managementActionHtml(issue, fallbackUrl) {
  const presentation = issuePresentation(issue);
  const targetLabels = { 'work-item': '작업항목', spec: '상위 작업', project: '프로젝트', 'git-repository': 'Git 저장소' };
  const targetUrl = issue.metadata?.remote || issue.metadata?.url || issue.metadata?.representativeCommit?.url || fallbackUrl;
  return `<div class="management-action"><strong>${esc(presentation.categoryLabel)} · ${esc(presentation.label)}</strong><small>현재 확인 사항: ${esc(issue.message || '세부 내용을 확인하세요.')}</small><small>수정 방법: ${esc(presentation.recommendedAction)}</small><small>권장 처리: ${esc(presentation.responsibleRole)} · ${esc(targetLabels[presentation.actionTarget] || 'Notion')}</small>${targetUrl ? `<div class="inline-actions"><a href="${esc(safeUrl(targetUrl))}" target="_blank" rel="noreferrer">수정할 항목 열기</a><button type="button" class="link-copy" data-copy-link="${esc(safeUrl(targetUrl))}">링크 복사</button></div>` : ''}</div>`;
}

export function issueGroupRowHtml(group, dashboard) {
  const issues = [...group.issues].sort((left, right) => (SEVERITY_RANK[left.severity] ?? 9) - (SEVERITY_RANK[right.severity] ?? 9));
  const primary = issues[0];
  const item = dashboard.workItems.find(work => work.id === primary.workItemId);
  const spec = dashboard.projects.flatMap(project => project.specs || []).find(row => row.id === primary.specId);
  const commit = dashboard.git?.commits?.find(row => row.hash === primary.metadata?.commitHash);
  const title = item?.title || spec?.title || (primary.metadata?.commitHash ? `커밋 ${primary.metadata.commitHash.slice(0, 8)}` : '프로젝트 관리 항목');
  const context = item ? `${item.spec || '상위 작업 미지정'} · ${item.team || '팀 미지정'}` : spec ? '상위 작업' : group.project;
  const summary = primaryActionSummary(issues);
  const categories = [...new Set(issues.map(issue => issuePresentation(issue).categoryLabel))];
  const detectedAt = issues.map(issue => issue.detectedAt).filter(Boolean).sort().at(-1);
  return `<details class="issue-row ${esc(group.severity)}"><summary><strong><span class="dot ${esc(group.severity)}"></span>${esc(title)} · ${esc(summary.label)}</strong><small>${esc(context)} · ${esc(categories.join(' · '))}${detectedAt ? ` · 감지 ${fmt(detectedAt)}` : ''}</small></summary><div class="management-actions">${issues.map(issue => managementActionHtml(issue, item?.url || spec?.url || commit?.url)).join('')}</div></details>`;
}

function kpi(key, value, label, tone, selectedDetail) {
  return `<button type="button" class="kpi ${tone} ${selectedDetail === key ? 'selected' : ''}" data-briefing-detail="${esc(key)}" aria-expanded="${selectedDetail === key}"><span class="value">${value ?? 0}</span><span class="label">${esc(label)}</span></button>`;
}

function briefingDetailHtml(dashboard, detail, taskRows, filters = {}) {
  if (!detail) return '';
  if (detail === 'git') {
    const rows = dashboard.projects.map(project => {
      const projectGitUrl = project.gitUrl || project.config?.gitUrl;
      const repository = dashboard.git.repositories.find(item => item.project === project.name || item.projectName === project.name)
        || (projectGitUrl && dashboard.git.repositories.find(item => item.remote === projectGitUrl || item.url === projectGitUrl))
        || { project: project.name, remote: projectGitUrl, status: projectGitUrl ? 'connected' : 'missing-url' };
      const mapping = repository.commitCount ? ` · 작업 연결 ${repository.mappedCommitCount || 0}/${repository.commitCount}` : '';
      const collectedBranches = repository.matchedBranches?.length ? repository.matchedBranches.join(', ') : repository.defaultBranch || '-';
      const unmatched = repository.unmatchedBranches?.length ? ` · 미확인 ${repository.unmatchedBranches.join(', ')}` : '';
      return `<div class="briefing-row"><strong>${esc(project.name)} · ${esc(gitRepositoryStatus(repository))}</strong><small>${esc(repository.remote || repository.url || projectGitUrl || 'Git URL 없음')} · 브랜치 ${esc(collectedBranches)}${esc(unmatched)} · 최근 활동 ${fmt(repository.latestCommitAt || repository.lastActivityAt || repository.recentGitAt)}${mapping}</small><small>마지막 수집 ${fmt(repository.lastFetchedAt)} · 출처 ${esc(repository.source || 'notion')}</small></div>`;
    });
    return `<section class="card briefing-detail" aria-live="polite"><h3>Git 저장소 수집 상세</h3>${rows.join('') || '<div class="summary">표시할 프로젝트가 없습니다.</div>'}</section>`;
  }
  const labels = {
    projects: '진행 중 프로젝트',
    'work-items': '진행 중 작업항목',
    overdue: '기한 초과 작업항목',
    guide: '가이드 위반 작업항목',
    setup: '진행 준비 필요 항목',
  };
  const allItems = briefingDetailItems(dashboard, detail);
  const items = briefingDetailItems(dashboard, detail, filters);
  if (detail === 'projects') return `<section class="card briefing-detail" aria-live="polite"><h3>${labels[detail]} ${items.length}개</h3>${items.map(project => `<div class="briefing-row"><strong>${esc(project.name)}</strong><small>진행 ${project.stats.inProgress}건 · 기한 초과 ${project.stats.overdue}건 · 관리 확인 ${project.stats.issueCount}건</small></div>`).join('') || '<div class="summary">해당 프로젝트가 없습니다.</div>'}</section>`;
  const shareActions = ['overdue', 'guide', 'setup'].includes(detail)
    ? `<div class="share-actions"><button type="button" class="share-primary" data-copy-slack data-share-detail="${esc(detail)}">복사</button></div>`
    : '';
  const filterToolbar = ['overdue', 'guide', 'setup'].includes(detail) ? briefingFilterHtml(allItems, filters) : '';
  return `<section class="card briefing-detail" aria-live="polite"><div class="detail-heading"><div><h3>${labels[detail]} ${items.length}개</h3>${shareActions ? '<p>현재 목록의 담당자·기한·확인사항·Notion 링크를 공유합니다.</p>' : ''}</div>${shareActions}</div>${filterToolbar}${taskRows(items, detail === 'overdue' ? 'overdue' : 'risk')}</section>`;
}

export function briefingHtml(dashboard, selectedDetail, taskRows, briefingFilters = {}) {
  const scopedKpis = (metrics, selectedDetail) => `<div class="kpis">${kpi('projects', metrics.activeProjects, '진행 중 프로젝트', 'info', selectedDetail)}${kpi('work-items', metrics.inProgressWorkItems, '진행 중 작업항목', 'normal', selectedDetail)}${kpi('overdue', metrics.overdueWorkItems, '기한 초과 작업항목', metrics.overdueWorkItems ? 'error' : '', selectedDetail)}${kpi('guide', metrics.guideViolationWorkItems, '가이드 위반 작업항목', metrics.guideViolationWorkItems ? 'error' : '', selectedDetail)}${kpi('setup', metrics.progressSetupRequiredItems, '진행 준비 필요 항목', metrics.progressSetupRequiredItems ? 'warning' : '', selectedDetail)}</div>`;
  const overallSummary = ['success', 'partial', 'stale'].includes(dashboard.ai?.analysisStatus)
    ? dashboard.ai?.overall?.summary
    : null;
  const analysisStatus = dashboard.ai?.analysisStatus;
  const analysisEmpty = analysisStatus === 'stale'
    ? '최신 업무 데이터 이후 통합 분석이 아직 실행되지 않았습니다.'
    : analysisStatus === 'failed' ? '통합 분석이 실패했습니다. 상단 데이터 수집 상태를 확인해 주세요.'
      : '통합 분석이 아직 실행되지 않았습니다.';
  const sourceBackedRisks = (dashboard.projects || []).map(project => {
    const candidates = (project.specInsights || []).flatMap(insight => (insight.evidence || [])
      .filter(item => item.attention)
      .map(item => ({ text: `[${project.name}] ${insight.title}: ${item.excerpt}`, timestamp: item.timestamp || '' })))
      .sort((left, right) => String(right.timestamp).localeCompare(String(left.timestamp)));
    return candidates[0]?.text || null;
  }).filter(Boolean);
  const agentRisks = ['success', 'partial', 'stale'].includes(analysisStatus) ? dashboard.ai?.overall?.topRisks || [] : [];
  const importantRisks = [...sourceBackedRisks, ...agentRisks]
    .filter((item, index, rows) => rows.findIndex(candidate => String(candidate).replace(/\s+/g, '') === String(item).replace(/\s+/g, '')) === index)
    .slice(0, 5);
  const importantRiskHtml = importantRisks.length
    ? `<div class="analysis-risks"><h4>중요 확인사항</h4>${importantRisks.map(risk => `<div class="briefing-row"><strong><span class="dot warning"></span>${esc(risk)}</strong></div>`).join('')}</div>`
    : '';
  return `<div class="section-head"><div><h2>오늘의 업무 브리핑</h2><p>통합 분석 → 어제와 달라진 것 → 스프린트별 업무 현황 순서입니다. 업무 원본에 대해 이 화면은 읽기 전용입니다.</p></div></div>
    ${selectedDetail === 'git' ? briefingDetailHtml(dashboard, 'git', taskRows, briefingFilters) : ''}
    <div class="bento">
    <div class="card span-6"><h3>1. 에이전트 통합 분석${analysisStatus === 'stale' ? ' · 갱신 필요' : ''}</h3>${overallSummary ? `<p class="summary analysis-summary">${esc(overallSummary)}</p>` : `<div class="summary">${esc(analysisEmpty)}</div>`}${importantRiskHtml}</div>
    <div class="card span-6"><h3>2. 어제와 달라진 것</h3>${dashboard.deltas.length ? dashboard.deltas.slice(0, 5).map(delta => `<div class="briefing-row"><strong><span class="dot info"></span>[${esc(delta.project)}] ${esc(delta.taskTitle || '프로젝트')} · ${esc(delta.field)}</strong><small>${esc(JSON.stringify(delta.from))} → ${esc(JSON.stringify(delta.to))}</small></div>`).join('') : `<div class="summary">${esc(dashboard.snapshotComparison?.reason || '변화가 감지되지 않았습니다.')}</div>`}</div>
    </div>${sprintOverviewHtml(dashboard, { kpisHtml: scopedKpis, initialDetail: selectedDetail, initialFilters: briefingFilters })}`;
}

